const { useEffect, useRef, useState } = React;

const CONTENT_HEIGHT = 560;
const TARGET_TOP = 470;

// 滚动地图：整列代表容器内容，浅色框是当前可见区域，圆点是输入框所在位置
const ScrollMap = ({ scrollTop, viewport }) => {
  const toPercent = value => `${(value / CONTENT_HEIGHT) * 100}%`;
  return (
    <div className="relative h-full w-3 shrink-0 rounded-full bg-hover">
      <div
        className="absolute inset-x-0 rounded-full border border-accent bg-accent-soft transition-[top] duration-200 ease-tau-out"
        style={{ top: toPercent(scrollTop), height: toPercent(viewport) }}
      />
      <div className="absolute left-1/2 size-2 -translate-x-1/2 rounded-full bg-warn" style={{ top: toPercent(TARGET_TOP + 16) }} />
    </div>
  );
};

const Component = () => {
  const containerRef = useRef(null);
  const inputRef = useRef(null);
  const frameRef = useRef(0);
  const [preventScroll, setPreventScroll] = useState(true);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewport, setViewport] = useState(180);
  const [focused, setFocused] = useState(false);
  const [last, setLast] = useState(null);

  useEffect(() => {
    const container = containerRef.current;
    const input = inputRef.current;
    const handleScroll = () => setScrollTop(container.scrollTop);
    const handleFocus = () => setFocused(true);
    const handleBlur = () => setFocused(false);
    setViewport(container.clientHeight || 180);
    container.addEventListener("scroll", handleScroll);
    input.addEventListener("focus", handleFocus);
    input.addEventListener("blur", handleBlur);
    return () => {
      cancelAnimationFrame(frameRef.current);
      container.removeEventListener("scroll", handleScroll);
      input.removeEventListener("focus", handleFocus);
      input.removeEventListener("blur", handleBlur);
    };
  }, []);

  const callFocus = () => {
    const container = containerRef.current;
    const before = container.scrollTop;
    inputRef.current.focus({ preventScroll });
    setFocused(document.activeElement === inputRef.current);
    cancelAnimationFrame(frameRef.current);
    // 等一帧再读，确保浏览器已完成聚焦引发的滚动
    frameRef.current = requestAnimationFrame(() => {
      setLast({ preventScroll, before, after: container.scrollTop });
      setScrollTop(container.scrollTop);
    });
  };

  const reset = () => {
    inputRef.current.blur();
    containerRef.current.scrollTop = 0;
    setScrollTop(0);
    setLast(null);
  };

  const scrolled = last && last.after !== last.before;

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex h-[200px] min-w-0 gap-3 rounded-tau-md border border-line-1 p-2.5">
          <div ref={containerRef} className="relative min-w-0 flex-1 overflow-y-auto rounded-tau-sm border border-dashed border-line-1">
            <div className="relative" style={{ height: CONTENT_HEIGHT }}>
              <div className="flex flex-col gap-1 p-3">
                <span className="text-tau-body text-ink-1">容器顶部</span>
                <span className="text-tau-sm text-ink-3">输入框在下方很远处，当前不可见</span>
              </div>
              <div className="absolute inset-x-3 flex items-center gap-2" style={{ top: TARGET_TOP }}>
                <input
                  ref={inputRef}
                  readOnly
                  placeholder="聚焦目标"
                  className="h-8 min-w-0 flex-1 rounded-tau-sm border border-line-1 bg-surface px-2.5 text-tau-body text-ink-1 outline-none focus:border-accent focus:ring-2 focus:ring-accent-soft"
                />
              </div>
            </div>
          </div>
          <ScrollMap scrollTop={scrollTop} viewport={viewport} />
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">调用结果</span>
          <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
            input.focus({`{ preventScroll: ${preventScroll} }`})
          </code>
          <div className="flex flex-col gap-1 font-tau-mono text-tau-meta text-ink-2">
            <span>{focused ? "焦点：输入框" : "焦点：不在输入框"}</span>
            <span>scrollTop：{Math.round(scrollTop)}px</span>
          </div>
          {last && (
            <div className="mt-auto flex items-center gap-2">
              <ui.Tag color={scrolled ? "orange" : "green"}>{scrolled ? "容器滚动了" : "容器没动"}</ui.Tag>
              <span className="font-tau-mono text-tau-sm text-ink-3">
                {Math.round(last.before)} → {Math.round(last.after)}px
              </span>
            </div>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Button variant="primary" size="sm" icon={icons.Crosshair} onClick={callFocus}>
          调用 focus()
        </ui.Button>
        <ui.Switch checked={preventScroll} onCheckedChange={setPreventScroll} label="preventScroll" size="sm" />
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={reset}>
          重置
        </ui.Button>
      </div>
    </div>
  );
};

const { useEffect, useRef, useState } = React;

const OPTIONS = [
  { value: "omit", label: "不传" },
  { value: "true", label: "true" },
  { value: "false", label: "false" },
];

const safeMatches = (element, selector) => {
  try {
    return element.matches(selector);
  } catch {
    return false;
  }
};

const Flag = ({ label, on }) => (
  <div className="flex items-center justify-between gap-3">
    <span className="font-tau-mono text-tau-meta text-ink-2">{label}</span>
    <ui.Tag color={on ? "blue" : "gray"}>{on ? "匹配" : "不匹配"}</ui.Tag>
  </div>
);

const Component = () => {
  const targetRef = useRef(null);
  const scriptedRef = useRef(false);
  const frameRef = useRef(0);
  const [option, setOption] = useState("true");
  const [state, setState] = useState({ focus: false, visible: false, source: null });
  const [supported, setSupported] = useState(null);

  const read = source => {
    const target = targetRef.current;
    setState({ focus: safeMatches(target, ":focus"), visible: safeMatches(target, ":focus-visible"), source });
  };

  useEffect(() => {
    const target = targetRef.current;
    // 键盘 Tab 进来或点击时，也同步读出伪类状态，便于和脚本聚焦对照
    const handleFocus = () => {
      if (scriptedRef.current) return;
      cancelAnimationFrame(frameRef.current);
      frameRef.current = requestAnimationFrame(() => read("用户操作"));
    };
    const handleBlur = () => setState({ focus: false, visible: false, source: null });
    target.addEventListener("focus", handleFocus);
    target.addEventListener("blur", handleBlur);
    return () => {
      cancelAnimationFrame(frameRef.current);
      target.removeEventListener("focus", handleFocus);
      target.removeEventListener("blur", handleBlur);
    };
  }, []);

  const callFocus = () => {
    const target = targetRef.current;
    target.blur();
    let optionRead = false;
    const options = { preventScroll: true };
    if (option !== "omit") {
      // 用 getter 探测浏览器是否会读取这个选项
      Object.defineProperty(options, "focusVisible", {
        enumerable: true,
        get: () => {
          optionRead = true;
          return option === "true";
        },
      });
    }
    scriptedRef.current = true;
    target.focus(options);
    scriptedRef.current = false;
    if (option !== "omit") setSupported(optionRead);
    read(`focus(${option === "omit" ? "" : `{ focusVisible: ${option} }`})`);
  };

  const code = option === "omit" ? "button.focus()" : `button.focus({ focusVisible: ${option} })`;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-target { outline: none; }
          .cb-target:focus-visible {
            outline: 2px solid var(--tau-accent);
            outline-offset: 3px;
          }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-h-[160px] min-w-0 flex-col items-center justify-center gap-3 rounded-tau-md border border-line-1 p-4">
          <button
            ref={targetRef}
            type="button"
            className="cb-target rounded-tau-sm border border-line-1 bg-surface px-4 py-2 text-tau-body text-ink-1 shadow-card"
          >
            目标按钮
          </button>
          <span className="text-tau-sm text-ink-3">{state.visible ? "outline 出现：匹配 :focus-visible" : "无 outline"}</span>
        </div>
        <div className="flex flex-col gap-2.5 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">伪类状态</span>
          <Flag label=":focus" on={state.focus} />
          <Flag label=":focus-visible" on={state.visible} />
          <span className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-3">
            来源：{state.source ?? "未聚焦"}
          </span>
          {supported !== null && (
            <span className="mt-auto text-tau-sm text-ink-3">
              {supported ? "当前浏览器会读取 focusVisible 选项" : "当前浏览器忽略 focusVisible 选项，按默认启发式决定"}
            </span>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-end gap-x-6 gap-y-3">
        <ui.RadioGroup label="focusVisible" value={option} onValueChange={setOption} orientation="horizontal">
          {OPTIONS.map(item => (
            <ui.Radio key={item.value} value={item.value} label={item.label} />
          ))}
        </ui.RadioGroup>
        <ui.Button variant="primary" size="sm" icon={icons.Crosshair} onClick={callFocus}>
          调用 focus()
        </ui.Button>
      </div>
      <code className="self-start rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{code}</code>
    </div>
  );
};
